import sys

def main():
    data = sys.stdin.read().split()
    if len(data) < 2:
        return

    a = data[0]
    b = data[1]

    length = max(len(a), len(b))
    a = a.zfill(length)
    b = b.zfill(length)

    rem_a = []
    rem_b = []

    for i in range(length - 1, -1, -1):
        da = a[i]
        db = b[i]

        if da < db:
            rem_b.append(db)
        elif db < da:
            rem_a.append(da)
        else:
            rem_a.append(da)
            rem_b.append(db)

    def build(rem):
        if not rem:
            return -1
        return int(''.join(reversed(rem)))

    result = [build(rem_a), build(rem_b)]
    result.sort()

    print(result[0], result[1])

if __name__ == "__main__":
    main()
